import zipfile
import xml.etree.ElementTree as ET
import re

NS = {
    'main': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'rel': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    letters, row = m.group(1), int(m.group(2))
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - 64)
    return idx - 1, row - 1  # 0-based col, 0-based row

def get_cell_map(sheet_xml):
    root = ET.fromstring(sheet_xml)
    cells = {}
    for row in root.iter('{%s}row' % NS['main']):
        for c in row.iter('{%s}c' % NS['main']):
            ref = c.get('r')
            if ref:
                col, r = col_to_idx(ref)
                cells[(r, col)] = c
    return cells

def read_shared_strings(xl):
    with xl.open('xl/sharedStrings.xml') as f:
        root = ET.fromstring(f.read())
    strings = []
    for si in root.iter('{%s}si' % NS['main']):
        texts = [t.text or '' for t in si.iter('{%s}t' % NS['main'])]
        strings.append(''.join(texts))
    return strings

def read_styles(xl):
    with xl.open('xl/styles.xml') as f:
        root = ET.fromstring(f.read())
    fmts = {}
    for numfmt in root.iter('{%s}numFmt' % NS['main']):
        fmts[numfmt.get('numFmtId')] = numfmt.get('formatCode')
    return fmts

def main():
    xl = zipfile.ZipFile('budget.xlsx')
    print("Files in archive:")
    for name in xl.namelist():
        print("  ", name)

    shared = read_shared_strings(xl)

    with xl.open('xl/workbook.xml') as f:
        wb_root = ET.fromstring(f.read())
    sheet_names = [s.get('name') for s in wb_root.iter('{%s}sheet' % NS['main'])]
    print("\nSheet names:", sheet_names)

    with xl.open('xl/_rels/workbook.xml.rels') as f:
        rel_root = ET.fromstring(f.read())
    rels = {r.get('Id'): r.get('Target') for r in rel_root.iter('{%s}Relationship' % NS['rel'])}

    for sheet in sheet_names:
        rid = None
        for s in wb_root.iter('{%s}sheet' % NS['main']):
            if s.get('name') == sheet:
                rid = s.get('{%s}id' % NS['rel'])
                break
        target = rels[rid]
        if not target.startswith('xl/'):
            target = 'xl/' + target
        with xl.open(target) as f:
            sheet_xml = f.read()
        cells = get_cell_map(sheet_xml)
        max_r = max(r for r, c in cells) + 1
        max_c = max(c for r, c in cells) + 1
        grid = [[''] * max_c for _ in range(max_r)]
        for (r, c), cell in cells.items():
            t = cell.get('t')
            v = cell.find('{%s}v' % NS['main'])
            value = ''
            if v is not None:
                if t == 's':
                    value = shared[int(v.text)]
                elif t == 'str' or t == 'inlineStr':
                    value = v.text or ''
                else:
                    value = v.text
            grid[r][c] = value
        print(f"\n=== Sheet: {sheet} ({max_r} rows x {max_c} cols) ===")
        for r in range(max_r):
            row = [str(grid[r][c]) for c in range(max_c)]
            if any(x != '' for x in row):
                print(f"r{r+1}: " + " | ".join(row))

main()

